#pragma once

#include <filesystem>
#include <cstdint>
#include <utility>
#include <string>

namespace r2fix {
class Startup;

// Rayman2Fix.ini is the only user-maintained configuration.
// ubi.ini is a game-facing compatibility file regenerated by the launcher.
// Preserve unrelated CD/game settings, e.g. Language.
// The primary monitor's native resolution is always selected automatically.
void synchronize_rayman2_ubi_ini(const std::filesystem::path& game_dir,
                                Startup& startup);

// Physical primary desktop size, DPI-aware on Windows/Wine.
// Linux uses 640x480 only as a synthetic headless test fallback.
std::pair<std::uint32_t,std::uint32_t> desktop_resolution();

// Pure geometry helper for deterministic tests on any host monitor.
std::pair<std::uint32_t,std::uint32_t> render_resolution_for_display(
    std::uint32_t width,std::uint32_t height,bool classic_4_3);

// 4:3 output is centered inside the physical canvas by GameFrame.
std::string configured_aspect_ratio(const std::filesystem::path& rayman2fix_ini);
bool configured_aspect_ratio_is_4_3(const std::filesystem::path& rayman2fix_ini);
std::pair<std::uint32_t, std::uint32_t> configured_render_resolution(
    const std::filesystem::path& rayman2fix_ini);

// jail_20 skip defaults to enabled; Learn_10 requires a separate opt-in.
bool configured_skip_cinematics(const std::filesystem::path& rayman2fix_ini);
bool configured_skip_learn10(const std::filesystem::path& rayman2fix_ini);

// Both GLI filtering features default to enabled (1), but retain independent
// per-user opt-outs (0). GameFrame 4:3 sidebars are never suppressed.
bool configured_remove_dialogue_backgrounds(const std::filesystem::path& rayman2fix_ini);
bool configured_remove_cinematic_bars(const std::filesystem::path& rayman2fix_ini);
bool configured_music_in_pause_menu(const std::filesystem::path& rayman2fix_ini);

// Add missing new options to existing INIs without discarding user settings.
void ensure_rayman2fix_ini_options(const std::filesystem::path& rayman2fix_ini);

// 60 FPS by default; 0 means unlimited, otherwise accept 15..240 FPS.
std::uint32_t configured_fps_limit(
    const std::filesystem::path& rayman2fix_ini);

} // namespace r2fix
